using System.Text.Json;

namespace DsBridge.Haptics;

/// <summary>Montage name -> game action class, generated by tools/haptic_intel.py (haptics/montages.generated.json) from the
/// structure of the asset names, the game's asset list and correlation with real journals. A montage event gets the fields
///   mc (class, e.g. weapon.draw / melee.attack / react.defeated), mw (weapon: s1h, fists, bow ...), md (direction L/R/T/B/F),
///   mstage (combo stage), mskill (Un/Tr/Ma), mconf (high|medium|low), mtiming (approx: the montage start is NOT the moment
///   of a hit or a sound - rules must say so).
/// Unknown names get mc=unknown (never guessed). Names cut short by the window-title transport are resolved by a unique prefix.</summary>
public sealed class MontageCatalog
{
    sealed record Entry(string Cls, Dictionary<string, string> Fields);
    readonly Dictionary<string, Entry> _byName = new(StringComparer.Ordinal);
    readonly List<string> _sorted = new();
    public int Count => _byName.Count;

    public static MontageCatalog Load(string path)
    {
        var c = new MontageCatalog();
        try
        {
            if (!File.Exists(path)) return c;
            using var d = JsonDocument.Parse(File.ReadAllText(path), new JsonDocumentOptions { CommentHandling = JsonCommentHandling.Skip, AllowTrailingCommas = true });
            foreach (var m in d.RootElement.GetProperty("montages").EnumerateObject())
            {
                var f = new Dictionary<string, string>();
                foreach (var p in m.Value.EnumerateObject())
                    if (p.Value.ValueKind is JsonValueKind.String or JsonValueKind.Number) f[p.Name] = p.Value.ToString();
                c._byName[m.Name] = new Entry(f.GetValueOrDefault("mc", "unknown"), f);
            }
            c._sorted.AddRange(c._byName.Keys.OrderBy(x => x, StringComparer.Ordinal));
        }
        catch { /* a broken generated file must never stop the companion: montages stay unclassified */ }
        return c;
    }

    Entry? Find(string name)
    {
        if (_byName.TryGetValue(name, out var e)) return e;
        if (name.Length < 12) return null;
        // truncated by the title transport: unique prefix
        int i = _sorted.BinarySearch(name, StringComparer.Ordinal);
        if (i < 0) i = ~i;
        if (i < _sorted.Count && _sorted[i].StartsWith(name, StringComparison.Ordinal) && (i + 1 >= _sorted.Count || !_sorted[i + 1].StartsWith(name, StringComparison.Ordinal)))
            return _byName[_sorted[i]];
        return null;
    }

    public GameEvent Annotate(GameEvent ev)
    {
        var m = ev.Get("m");
        if (m == null || _byName.Count == 0) return ev;
        var ctx = new Dictionary<string, string>(ev.Ctx);
        var e = Find(m);
        if (e == null) { ctx["mc"] = "unknown"; return ev with { Ctx = ctx }; }
        foreach (var (k, v) in e.Fields) ctx[k] = v;
        return ev with { Ctx = ctx };
    }
}
